using UnityEngine;using System;using System.Collections.Generic;using System.Linq;using System.IO;using System.Text;using System.Security.Cryptography;using Game.Skirmish.Contracts;
namespace Game.Configs {
// Optional explicit layout data. Absence preserves packaged kind-pad/offset behavior.
public static class SkirmishStructureInstanceBinding {
 static bool Finite(float value)=>!float.IsNaN(value)&&!float.IsInfinity(value);
 static string Key(byte faction,string id,int ordinal)=>faction+"/"+id+"/"+ordinal;
 static void Bad(List<SkirmishCompileReason> reasons,string error)=>reasons?.Add(new SkirmishCompileReason(SkirmishReasonCode.InsufficientAnchor,"structureInstancePads",error));
 public static bool TryApply(SkirmishMapLayoutConfig layout,SkirmishResolvedSetup setup,List<SkirmishCompileReason> reasons){var rows=layout?.StructureInstancePads;if(rows==null||rows.Length==0)return true;if(setup?.Structures==null||layout.Pads==null||layout.Anchors==null||rows.Length>512||!Finite(layout.OriginX)||!Finite(layout.OriginZ)||!Finite(layout.WorldWidthMetres)||!Finite(layout.WorldDepthMetres)||!Finite(layout.CellSize)||layout.WorldWidthMetres<=0||layout.WorldDepthMetres<=0||layout.CellSize<=0){Bad(reasons,"Complete bounded canonical structure domain required");return false;}var keys=new HashSet<string>();foreach(var row in rows){if(row.SizeId<SkirmishSizeId.Standard||row.SizeId>SkirmishSizeId.LargeWar||(int)row.DifficultyId<1||(int)row.DifficultyId>4||row.FactionId<1||row.FactionId>2||row.InstanceOrdinal<0||row.InstanceOrdinal>255||string.IsNullOrEmpty(row.StructureId)||string.IsNullOrEmpty(SkirmishStructureIds.VisualKey(row.StructureId))||string.IsNullOrEmpty(row.PadId)||string.IsNullOrEmpty(row.AnchorId)||!keys.Add((int)row.SizeId+"/"+(int)row.DifficultyId+"/"+Key(row.FactionId,row.StructureId,row.InstanceOrdinal))){Bad(reasons,"Duplicate/unknown/invalid instance binding key");return false;}}
 var selected=rows.Where(r=>r.SizeId==setup.SizeId&&r.DifficultyId==setup.DifficultyId).ToArray();if(selected.Length!=setup.Structures.Length){Bad(reasons,"Present layout mapping must cover exactly this size/difficulty canonical structure domain");return false;}var byKey=selected.ToDictionary(r=>Key(r.FactionId,r.StructureId,r.InstanceOrdinal));var seen=new Dictionary<string,int>();var padsUsed=new HashSet<string>();var anchorsUsed=new HashSet<string>();var changed=(SkirmishResolvedStructureEntry[])setup.Structures.Clone();for(int i=0;i<changed.Length;i++){var structure=changed[i];string stem=Key(structure.FactionId,structure.StructureId,0);int ordinal=seen.TryGetValue(stem,out var n)?n:0;seen[stem]=ordinal+1;if(!byKey.TryGetValue(Key(structure.FactionId,structure.StructureId,ordinal),out var row)){Bad(reasons,"Missing/foreign canonical structure instance");return false;}var pads=layout.Pads.Where(p=>p.PadId==row.PadId).ToArray();var anchors=layout.Anchors.Where(a=>a.AnchorId==row.AnchorId).ToArray();if(pads.Length!=1||anchors.Length!=1||!padsUsed.Add(row.PadId)||!anchorsUsed.Add(row.AnchorId)||pads[0].AnchorId!=row.AnchorId||pads[0].FactionId!=structure.FactionId||pads[0].Kind!=SkirmishMapLayoutBuilder.PadKindForStructure(structure.StructureId)||!Finite(pads[0].CenterX)||!Finite(pads[0].CenterZ)||!Finite(pads[0].WidthMetres)||!Finite(pads[0].DepthMetres)||pads[0].WidthMetres<=0||pads[0].DepthMetres<=0||pads[0].CenterX-pads[0].WidthMetres*.5f<layout.OriginX||pads[0].CenterX+pads[0].WidthMetres*.5f>layout.OriginX+layout.WorldWidthMetres||pads[0].CenterZ-pads[0].DepthMetres*.5f<layout.OriginZ||pads[0].CenterZ+pads[0].DepthMetres*.5f>layout.OriginZ+layout.WorldDepthMetres||!layout.TryProjectLocalToMap(pads[0].CenterX,pads[0].CenterZ,out float x,out float z)||float.IsNaN(x)||float.IsInfinity(x)||float.IsNaN(z)||float.IsInfinity(z)){Bad(reasons,"Ambiguous/foreign frame, pad, anchor or dimensions: canonical="+Key(structure.FactionId,structure.StructureId,ordinal)+" pad="+row.PadId+" actualKind="+(pads.Length==1?pads[0].Kind.ToString():"count="+pads.Length)+" expectedKind="+SkirmishMapLayoutBuilder.PadKindForStructure(structure.StructureId)+" anchors="+anchors.Length);return false;}if(!Finite(anchors[0].NormalizedU)||!Finite(anchors[0].NormalizedV)||anchors[0].NormalizedU<0||anchors[0].NormalizedU>1||anchors[0].NormalizedV<0||anchors[0].NormalizedV>1||!Finite(anchors[0].WorldX)||!Finite(anchors[0].WorldZ)||Math.Abs(anchors[0].WorldX-pads[0].CenterX)>.001f||Math.Abs(anchors[0].WorldZ-pads[0].CenterZ)>.001f||!layout.TryProjectToMap(anchors[0].NormalizedU,anchors[0].NormalizedV,out float ax,out float az)||Math.Abs(ax-x)>.001f||Math.Abs(az-z)>.001f){Bad(reasons,"Anchor and preferred pad frame disagree");return false;}structure.SpawnAnchorId=row.AnchorId;structure.AcrossOffsetMetres=0;structure.ForwardOffsetMetres=0;structure.SpawnWorldX=x;structure.SpawnWorldZ=z;changed[i]=structure;}setup.Structures=changed;return true;}
 public static bool TryDeclaredContext(SkirmishMapLayoutConfig layout,SkirmishResolvedSetup setup,List<SkirmishCompileReason> reasons,out Vector2 player,out Vector2 enemy){player=default;enemy=default;var declared=layout?.DeclaredConfiguration;if(declared==null)return false;var rows=layout.StructureInstancePads;if(setup==null||declared.SizeId!=setup.SizeId||declared.DifficultyId!=setup.DifficultyId||rows.Length==0||rows.Any(r=>r.SizeId!=declared.SizeId||r.DifficultyId!=declared.DifficultyId)||layout.WorldBinding.HasMeasuredDeployments||layout.WorldBinding.BindAllConfigurations||!Finite(declared.PlayerDeployment.x)||!Finite(declared.PlayerDeployment.y)||!Finite(declared.EnemyDeployment.x)||!Finite(declared.EnemyDeployment.y)){Bad(reasons,"Present declaration requires exact single tuple, full instance mapping and unmeasured scope");return false;}var validate=new SkirmishResolvedSetup{SizeId=setup.SizeId,DifficultyId=setup.DifficultyId,Structures=setup.Structures};if(!TryApply(layout,validate,reasons))return false;player=declared.PlayerDeployment;enemy=declared.EnemyDeployment;return true;}
 public static bool IsExplicitInstanceOnlyPad(SkirmishMapLayoutConfig layout,SkirmishResolvedSetup setup,SkirmishLegalPadConfig pad){if(pad.Kind!=SkirmishLegalPadKind.Supply&&pad.Kind!=SkirmishLegalPadKind.Service&&pad.Kind!=SkirmishLegalPadKind.SupplyExpansion)return false;var rows=layout.StructureInstancePads;return layout.Pads.Where(p=>p.FactionId==pad.FactionId&&p.Kind==pad.Kind).All(p=>rows.Count(r=>r.SizeId==setup.SizeId&&r.DifficultyId==setup.DifficultyId&&r.FactionId==p.FactionId&&r.PadId==p.PadId&&r.AnchorId==p.AnchorId)==1);}
 public static string AppendLayoutFingerprint(string original,SkirmishMapLayoutConfig layout){var rows=layout?.StructureInstancePads;var declaration=layout?.DeclaredConfiguration;if((rows==null||rows.Length==0)&&declaration==null)return original;using var stream=new MemoryStream();using(var writer=new BinaryWriter(stream,Encoding.UTF8,true)){writer.Write("SkirmishStructureInstancePads/v1");writer.Write(original);writer.Write(declaration!=null);if(declaration!=null){writer.Write((int)declaration.SizeId);writer.Write((int)declaration.DifficultyId);writer.Write(declaration.PlayerDeployment.x);writer.Write(declaration.PlayerDeployment.y);writer.Write(declaration.EnemyDeployment.x);writer.Write(declaration.EnemyDeployment.y);}writer.Write(rows.Length);foreach(var row in rows){writer.Write((int)row.SizeId);writer.Write((int)row.DifficultyId);writer.Write(row.FactionId);writer.Write(row.StructureId??"");writer.Write(row.InstanceOrdinal);writer.Write(row.PadId??"");writer.Write(row.AnchorId??"");}}using var hash=SHA256.Create();return BitConverter.ToString(hash.ComputeHash(stream.ToArray())).Replace("-","").ToLowerInvariant();}
}}
